// Parse PagBank Payment Notification
// Handles PagBank webhook format for payment status updates

const input = $input.all()[0].json;
const body = input.body || input;

// PagBank sends charges array with status
const charges = body.charges || [];
const charge = charges[0] || {};

const paymentData = {
  payment_id: body.id || charge.id || '',
  reference_id: body.reference_id || '',
  status: charge.status || body.status || 'UNKNOWN',
  paid_at: charge.paid_at || null,
  amount: charge.amount?.value || body.amount?.value || 0,
  payer_name: charge.payment_method?.pix?.holder?.name || body.customer?.name || '',
  payer_tax_id: charge.payment_method?.pix?.holder?.tax_id || body.customer?.tax_id || '',
  is_paid: false
};

// Check if payment is confirmed
const paidStatuses = ['PAID', 'AUTHORIZED', 'AVAILABLE', 'CONFIRMED'];
paymentData.is_paid = paidStatuses.includes(paymentData.status.toUpperCase());

// Extract user phone from reference_id (format: DW_PHONE_TIMESTAMP)
if (paymentData.reference_id && paymentData.reference_id.startsWith('DW_')) {
  const parts = paymentData.reference_id.split('_');
  if (parts.length >= 2) {
    paymentData.user_number = parts[1];
  }
}

return paymentData;

