// Parse Supabase Database Webhook for Prescription
// Handles Supabase database webhook format (from database triggers) and legacy manual webhook format

const input = $input.all()[0].json;
const body = input.body || {};

let prescriptionData = null;
let prescriptionId = null;

// Check if it's a Supabase database webhook format
// Supabase sends: { type: 'INSERT'/'UPDATE', table: 'prescricoes', record: {...}, old_record: {...} }
if (body.type && (body.table === 'prescricoes' || body.table_name === 'prescricoes') && body.record) {
  // Supabase database webhook format
  prescriptionData = body.record;
  prescriptionId = body.record.id;

  // Only process if prescription hasn't been sent yet (verification check)
  if (prescriptionData.enviado_whatsapp === true) {
    // Skip if already sent
    return { 
      skip: true, 
      reason: 'Prescription already sent', 
      prescription_id: prescriptionId 
    };
  }

  // Only process INSERT or UPDATE events
  if (body.type !== 'INSERT' && body.type !== 'UPDATE') {
    return { 
      skip: true, 
      reason: 'Not an INSERT or UPDATE event', 
      prescription_id: prescriptionId 
    };
  }

  // Return the record data directly for processing
  return {
    skip: false,
    prescription_id: prescriptionId,
    prescription_data: prescriptionData,
    is_supabase_webhook: true
  };
} else {
  // Legacy webhook format (manual trigger or app trigger)
  prescriptionId = body.prescription_id || body.id || body.record?.id;
  if (!prescriptionId) {
    return { skip: true, reason: 'No prescription_id provided' };
  }

  return {
    skip: false,
    prescription_id: prescriptionId,
    prescription_data: null, // Will fetch it
    is_supabase_webhook: false
  };
}

