// Medication Safety Check Tool
// Comprehensive drug safety verification for dental prescriptions

// Input parsing
const input = $input.all()[0].json;
const prescribedMeds = (input.prescribed_medications || '').toLowerCase();
const allergies = (input.patient_allergies || '').toLowerCase();
const currentMeds = (input.current_medications || '').toLowerCase();
const conditions = (input.health_conditions || '').toLowerCase();

// Drug database - common dental medications and their interactions
const drugDatabase = {
  // Penicillins and related antibiotics
  penicillins: {
    names: ['amoxicilina', 'amoxicillin', 'ampicilina', 'penicilina', 'penicillin'],
    allergyKeywords: ['penicilina', 'penicillin', 'amoxicilina', 'ampicilina', 'beta-lactâmico', 'beta-lactamico'],
    crossAllergies: ['cefalosporina', 'cephalosporin'],
    interactions: [],
    contraindications: []
  },
  // NSAIDs (Anti-inflammatory)
  nsaids: {
    names: ['ibuprofeno', 'ibuprofen', 'diclofenaco', 'nimesulida', 'naproxeno', 'cetoprofeno', 'meloxicam', 'piroxicam', 'aine', 'anti-inflamatório'],
    allergyKeywords: ['aine', 'nsaid', 'anti-inflamatório', 'ibuprofeno', 'diclofenaco', 'aspirina'],
    crossAllergies: ['aspirina', 'aas'],
    interactions: ['anticoagulante', 'warfarina', 'heparina', 'rivaroxabana', 'apixabana', 'marevan', 'coumadin'],
    contraindications: ['úlcera', 'ulcera', 'gastrite', 'hemorragia', 'insuficiência renal', 'insuficiencia renal']
  },
  // Analgesics
  analgesics: {
    names: ['paracetamol', 'acetaminofeno', 'dipirona', 'novalgina', 'tylenol'],
    allergyKeywords: ['dipirona', 'metamizol', 'paracetamol'],
    crossAllergies: [],
    interactions: [],
    contraindications: []
  },
  // Corticosteroids
  corticosteroids: {
    names: ['dexametasona', 'prednisona', 'prednisolona', 'betametasona', 'hidrocortisona', 'corticoide', 'corticosteroide'],
    allergyKeywords: ['corticoide', 'corticosteroide'],
    crossAllergies: [],
    interactions: ['insulina', 'metformina', 'glibenclamida', 'antidiabético'],
    contraindications: ['diabetes', 'diabético', 'glicemia alta', 'hiperglicemia']
  },
  // Local anesthetics
  anesthetics: {
    names: ['lidocaína', 'lidocaina', 'articaína', 'mepivacaína', 'prilocaína', 'bupivacaína', 'anestésico'],
    allergyKeywords: ['lidocaína', 'lidocaina', 'anestésico local'],
    crossAllergies: [],
    interactions: ['betabloqueador', 'propranolol', 'atenolol', 'metoprolol'],
    contraindications: ['arritmia', 'taquicardia', 'problema cardíaco', 'problema cardiaco']
  },
  // Anticoagulants (patient may be taking)
  anticoagulants: {
    names: ['warfarina', 'marevan', 'heparina', 'rivaroxabana', 'xarelto', 'apixabana', 'eliquis', 'dabigatrana', 'pradaxa', 'anticoagulante'],
    allergyKeywords: [],
    crossAllergies: [],
    interactions: ['aine', 'ibuprofeno', 'diclofenaco', 'aspirina', 'aas'],
    contraindications: []
  },
  // Metronidazole
  metronidazole: {
    names: ['metronidazol', 'flagyl'],
    allergyKeywords: ['metronidazol'],
    crossAllergies: [],
    interactions: ['álcool', 'alcool', 'etanol', 'bebida alcoólica'],
    contraindications: []
  },
  // Clindamycin (alternative to penicillin)
  clindamycin: {
    names: ['clindamicina', 'dalacin'],
    allergyKeywords: ['clindamicina'],
    crossAllergies: ['lincomicina'],
    interactions: [],
    contraindications: ['colite', 'diarreia crônica']
  }
};

// Initialize results
const warnings = [];
const alerts = [];
const recommendations = [];
let isSafe = true;

// Function to check if text contains any keyword from array
function containsAny(text, keywords) {
  return keywords.some(keyword => text.includes(keyword));
}

// Check each drug category
for (const [category, drug] of Object.entries(drugDatabase)) {
  // Check if this drug is being prescribed
  const isPrescribed = containsAny(prescribedMeds, drug.names);

  if (isPrescribed) {
    // 1. Check direct allergies
    if (containsAny(allergies, drug.allergyKeywords)) {
      isSafe = false;
      alerts.push(`🚨 ALERGIA DETECTADA: Paciente tem alergia a ${drug.allergyKeywords.find(k => allergies.includes(k))}. NÃO prescrever ${drug.names[0]}!`);
    }

    // 2. Check cross-allergies
    if (drug.crossAllergies.length > 0 && containsAny(allergies, drug.crossAllergies)) {
      isSafe = false;
      alerts.push(`⚠️ ALERGIA CRUZADA: Paciente pode ter reação a ${drug.names[0]} devido a alergia a ${drug.crossAllergies.find(k => allergies.includes(k))}.`);
    }

    // 3. Check drug interactions with current medications
    if (drug.interactions.length > 0 && containsAny(currentMeds, drug.interactions)) {
      const interactingDrug = drug.interactions.find(k => currentMeds.includes(k));
      warnings.push(`⚠️ INTERAÇÃO MEDICAMENTOSA: ${drug.names[0]} pode interagir com ${interactingDrug} que o paciente está tomando.`);
      if (category === 'nsaids' && containsAny(currentMeds, ['anticoagulante', 'warfarina', 'heparina', 'rivaroxabana', 'apixabana'])) {
        isSafe = false;
        alerts.push(`🚨 RISCO DE SANGRAMENTO: AINEs + anticoagulantes aumentam risco de hemorragia. Considerar paracetamol como alternativa.`);
      }
    }

    // 4. Check contraindications based on health conditions
    if (drug.contraindications.length > 0 && containsAny(conditions, drug.contraindications)) {
      const condition = drug.contraindications.find(k => conditions.includes(k));
      warnings.push(`⚠️ CONTRAINDICAÇÃO: ${drug.names[0]} pode ser problemático para paciente com ${condition}.`);
      if (category === 'corticosteroids' && containsAny(conditions, ['diabetes', 'diabético'])) {
        alerts.push(`🚨 DIABÉTICO: Corticosteroides podem aumentar glicemia. Monitorar níveis de açúcar no sangue.`);
      }
    }
  }

  // Special check: patient taking anticoagulants and being prescribed NSAIDs
  if (category === 'anticoagulants' && containsAny(currentMeds, drug.names)) {
    if (containsAny(prescribedMeds, drugDatabase.nsaids.names)) {
      isSafe = false;
      alerts.push(`🚨 ALTO RISCO: Paciente usa anticoagulante. AINEs podem causar sangramento grave. Use paracetamol ou dipirona.`);
    }
  }
}

// Special recommendations
if (containsAny(allergies, ['penicilina', 'amoxicilina'])) {
  recommendations.push(`💡 ALTERNATIVA: Para pacientes alérgicos a penicilina, considerar Clindamicina 300mg ou Azitromicina 500mg.`);
}

if (containsAny(conditions, ['gravidez', 'grávida', 'gestante', 'gestação'])) {
  warnings.push(`⚠️ GESTANTE: Verificar segurança de todos os medicamentos na gravidez. Evitar AINEs no terceiro trimestre.`);
}

if (containsAny(conditions, ['amamentação', 'amamentando', 'lactante', 'aleitamento'])) {
  warnings.push(`⚠️ LACTANTE: Alguns medicamentos passam para o leite materno. Verificar compatibilidade.`);
}

// Build response
let response = '';

if (alerts.length > 0) {
  response += '🚨 **ALERTAS CRÍTICOS:**\n';
  response += alerts.join('\n') + '\n\n';
}

if (warnings.length > 0) {
  response += '⚠️ **AVISOS:**\n';
  response += warnings.join('\n') + '\n\n';
}

if (recommendations.length > 0) {
  response += '💡 **RECOMENDAÇÕES:**\n';
  response += recommendations.join('\n') + '\n\n';
}

if (isSafe && alerts.length === 0 && warnings.length === 0) {
  response = '✅ **VERIFICAÇÃO CONCLUÍDA:** Nenhuma contraindicação ou interação medicamentosa grave detectada com base nas informações fornecidas. Sempre confirme com o histórico completo do paciente.';
}

return {
  safe: isSafe,
  alerts: alerts,
  warnings: warnings,
  recommendations: recommendations,
  summary: response,
  prescribed_medications: prescribedMeds,
  patient_allergies: allergies,
  current_medications: currentMeds,
  health_conditions: conditions
};

