// Parse Structured AI Output
// Extracts structured fields from AI agent output according to gerar_resumo_diagnostico format

const aiOutput = $('RECEPCIONISTA').item.json.output || '';

// Initialize parsed structure
const parsed = {
  resumo_sintomas: '',
  diagnostico_sugerido: '',
  tratamento_sugerido: '',
  urgencia: 'Média',
  alertas: '',
  raw_output: aiOutput
};

// Try to parse JSON if the output is structured JSON
let structuredData = null;
try {
  // Check if output contains JSON structure
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    structuredData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Not JSON, will parse as text
}

if (structuredData) {
  // Direct JSON structure
  parsed.resumo_sintomas = structuredData.resumo_sintomas || structuredData.sintomas || '';
  parsed.diagnostico_sugerido = structuredData.diagnostico_sugerido || structuredData.diagnostico || '';
  parsed.tratamento_sugerido = structuredData.tratamento_sugerido || structuredData.tratamento || '';
  parsed.urgencia = structuredData.urgencia || structuredData.urgency || 'Média';
  parsed.alertas = structuredData.alertas || structuredData.alerts || '';
} else {
  // Parse from text format (common patterns)
  const text = aiOutput;

  // Extract symptoms summary (look for keywords)
  const symptomsPatterns = [
    /sintomas[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /resumo[\s]*dos[\s]*sintomas[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /paciente[\s]*relata[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i
  ];

  for (const pattern of symptomsPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      parsed.resumo_sintomas = match[1].trim();
      break;
    }
  }

  // Extract diagnosis (look for diagnostic keywords)
  const diagnosisPatterns = [
    /diagnóstico[\s]*sugerido[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /possível[\s]*diagnóstico[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /hipótese[\s]*diagnóstica[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /diagnóstico[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i
  ];

  for (const pattern of diagnosisPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      parsed.diagnostico_sugerido = match[1].trim();
      break;
    }
  }

  // Extract treatment suggestion
  const treatmentPatterns = [
    /tratamento[\s]*sugerido[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /sugestão[\s]*de[\s]*tratamento[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /recomendação[\s]*inicial[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /tratamento[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i
  ];

  for (const pattern of treatmentPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      parsed.tratamento_sugerido = match[1].trim();
      break;
    }
  }

  // Extract urgency level
  const urgencyPatterns = [
    /urgência[\s:]*([^\n]+)/i,
    /nível[\s]*de[\s]*urgência[\s:]*([^\n]+)/i
  ];

  for (const pattern of urgencyPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      const urgencyText = match[1].trim().toLowerCase();
      if (urgencyText.includes('crítica') || urgencyText.includes('critica')) {
        parsed.urgencia = 'Crítica';
      } else if (urgencyText.includes('alta')) {
        parsed.urgencia = 'Alta';
      } else if (urgencyText.includes('baixa')) {
        parsed.urgencia = 'Baixa';
      } else if (urgencyText.includes('média') || urgencyText.includes('media')) {
        parsed.urgencia = 'Média';
      }
      break;
    }
  }

  // Check for urgency keywords in text
  const urgencyKeywords = {
    'Crítica': ['crítica', 'critica', 'emergência', 'emergencia', 'urgente', 'imediato'],
    'Alta': ['alta', 'importante', 'prioridade'],
    'Baixa': ['baixa', 'rotina', 'não urgente']
  };

  const lowerText = text.toLowerCase();
  for (const [level, keywords] of Object.entries(urgencyKeywords)) {
    if (keywords.some(kw => lowerText.includes(kw))) {
      parsed.urgencia = level;
      break;
    }
  }

  // Extract alerts/warnings
  const alertPatterns = [
    /alertas?[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /avisos?[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i,
    /atenção[\s:]*([^\n]+(?:\.\s*[^\n]+)*)/i
  ];

  for (const pattern of alertPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      parsed.alertas = match[1].trim();
      break;
    }
  }

  // If no structured data found, use the entire output as symptoms summary
  if (!parsed.resumo_sintomas && !parsed.diagnostico_sugerido) {
    parsed.resumo_sintomas = aiOutput.substring(0, 500); // Limit length
  }
}

// Return parsed structure
return {
  ...parsed,
  parse_success: !!(parsed.diagnostico_sugerido || parsed.tratamento_sugerido || parsed.resumo_sintomas)
};

// Format Prescription Message
// Formats prescription data into a readable WhatsApp message

// Get prescription data from either merged data (new flow) or Get Prescription (old flow)
let prescription;
try {
  prescription = $('Merge Prescription Data').item.json;
} catch (e) {
  prescription = $('Get Prescription1').item.json;
}
const patient = $('Get Patient for Prescription1').item.json;
// Get profile data from merged node (handles both cases: with and without profile_id)
let profile;
try {
  profile = $('Merge Profile Data for Prescription').item.json || {};
} catch (e) {
  profile = {};
}

const patientName = patient?.nome || profile?.name || 'Paciente';
const date = prescription?.created_at ? new Date(prescription.created_at).toLocaleDateString('pt-BR') : new Date().toLocaleDateString('pt-BR');

let message = `📋 *PRESCRIÇÃO ODONTOLÓGICA*\n\n`;
message += `Paciente: ${patientName}\n`;
message += `Data: ${date}\n\n`;

// Add diagnosis if available
if (prescription?.diagnostico || prescription?.diagnostico_final) {
  message += `*Diagnóstico:*\n${prescription.diagnostico || prescription.diagnostico_final}\n\n`;
}

// Add medications
if (prescription?.medicacoes || prescription?.medicamentos) {
  message += `*Medicamentos Prescritos:*\n`;
  const medications = prescription.medicacoes || prescription.medicamentos;

  if (typeof medications === 'string') {
    try {
      const meds = JSON.parse(medications);
      meds.forEach((med, index) => {
        message += `${index + 1}. *${med.nome || med.name || 'Medicamento'}*\n`;
        if (med.dosagem || med.dosage) message += `   Dosagem: ${med.dosagem || med.dosage}\n`;
        if (med.frequencia || med.frequency) message += `   Frequência: ${med.frequencia || med.frequency}\n`;
        if (med.duracao || med.duration) message += `   Duração: ${med.duracao || med.duration}\n`;
        if (med.observacoes || med.notes) message += `   Observações: ${med.observacoes || med.notes}\n`;
        message += `\n`;
      });
    } catch (e) {
      message += `${medications}\n\n`;
    }
  } else if (Array.isArray(medications)) {
    medications.forEach((med, index) => {
      message += `${index + 1}. *${med.nome || med.name || 'Medicamento'}*\n`;
      if (med.dosagem || med.dosage) message += `   Dosagem: ${med.dosagem || med.dosage}\n`;
      if (med.frequencia || med.frequency) message += `   Frequência: ${med.frequencia || med.frequency}\n`;
      if (med.duracao || med.duration) message += `   Duração: ${med.duracao || med.duration}\n`;
      if (med.observacoes || med.notes) message += `   Observações: ${med.observacoes || med.notes}\n`;
      message += `\n`;
    });
  } else {
    message += `${medications}\n\n`;
  }
}

// Add treatment instructions
if (prescription?.instrucoes || prescription?.instructions || prescription?.tratamento_realizado) {
  message += `*Instruções de Tratamento:*\n${prescription.instrucoes || prescription.instructions || prescription.tratamento_realizado}\n\n`;
}

// Add observations
if (prescription?.observacoes || prescription?.observations) {
  message += `*Observações:*\n${prescription.observacoes || prescription.observations}\n\n`;
}

// Add safety warnings if available
if (prescription?.alertas || prescription?.warnings) {
  message += `⚠️ *Atenção:*\n${prescription.alertas || prescription.warnings}\n\n`;
}

message += `🦷 *Dental Wizard*\n`;
message += `Em caso de dúvidas, entre em contato conosco.`;

// Get phone number
const phoneNumber = profile?.phone || patient?.telefone || prescription?.telefone || '';

return {
  message: message,
  phone_number: phoneNumber,
  prescription_id: prescription?.id,
  patient_id: patient?.id || prescription?.paciente_id
};

// Parse Supabase Database Webhook
// Handles Supabase database webhook format (from database triggers) and legacy manual webhook format

const input = $input.all()[0].json;
const body = input.body || {};

let atendimentoData = null;
let atendimentoId = null;

// Check if it's a Supabase database webhook format
// Supabase sends: { type: 'UPDATE', table: 'atendimentos', record: {...}, old_record: {...} }
if (body.type && (body.table === 'atendimentos' || body.table_name === 'atendimentos') && body.record) {
  // Supabase database webhook format
  atendimentoData = body.record;
  atendimentoId = body.record.id;

  // Only process if diagnostico_final and tratamento_realizado are filled
  if (!atendimentoData.diagnostico_final || !atendimentoData.tratamento_realizado) {
    // Skip if dentist hasn't filled in the diagnosis/treatment yet
    return { 
      skip: true, 
      reason: 'Diagnosis or treatment not yet filled', 
      atendimento_id: atendimentoId 
    };
  }

  // Only process UPDATE events (not INSERT)
  if (body.type !== 'UPDATE') {
    return { 
      skip: true, 
      reason: 'Not an UPDATE event', 
      atendimento_id: atendimentoId 
    };
  }

  // Return the record data directly for processing
  return {
    skip: false,
    atendimento_id: atendimentoId,
    atendimento_data: atendimentoData,
    is_supabase_webhook: true
  };
} else {
  // Legacy webhook format (manual trigger or app trigger)
  atendimentoId = body.atendimento_id || body.id || body.record?.id;
  if (!atendimentoId) {
    return { skip: true, reason: 'No atendimento_id provided' };
  }

  return {
    skip: false,
    atendimento_id: atendimentoId,
    atendimento_data: null, // Will fetch it
    is_supabase_webhook: false
  };
}

// ML Comparison Logic
// Compares AI suggested diagnosis with dentist's final diagnosis

const atendimento = $input.all()[0].json;

const aiDiagnosis = (atendimento.diagnostico_sugerido || '').toLowerCase();
const dentistDiagnosis = (atendimento.diagnostico_final || '').toLowerCase();
const aiTreatment = (atendimento.medicacoes_sugeridas || atendimento.tratamento_sugerido || '').toLowerCase();
const dentistTreatment = (atendimento.tratamento_realizado || '').toLowerCase();

// Calculate similarity scores (simple keyword matching)
function calculateSimilarity(text1, text2) {
  if (!text1 || !text2) return 0;

  const words1 = text1.split(/\s+/).filter(w => w.length > 3);
  const words2 = text2.split(/\s+/).filter(w => w.length > 3);

  if (words1.length === 0 || words2.length === 0) return 0;

  const matches = words1.filter(w => words2.some(w2 => w2.includes(w) || w.includes(w2)));
  return (matches.length / Math.max(words1.length, words2.length)) * 100;
}

const diagnosisSimilarity = calculateSimilarity(aiDiagnosis, dentistDiagnosis);
const treatmentSimilarity = calculateSimilarity(aiTreatment, dentistTreatment);

const mlData = {
  atendimento_id: atendimento.id,
  paciente_id: atendimento.paciente_id,
  ai_diagnosis: atendimento.diagnostico_sugerido || '',
  dentist_diagnosis: atendimento.diagnostico_final || '',
  ai_treatment: atendimento.medicacoes_sugeridas || atendimento.tratamento_sugerido || '',
  dentist_treatment: atendimento.tratamento_realizado || '',
  diagnosis_accuracy: diagnosisSimilarity.toFixed(2),
  treatment_accuracy: treatmentSimilarity.toFixed(2),
  overall_accuracy: ((diagnosisSimilarity + treatmentSimilarity) / 2).toFixed(2),
  timestamp: new Date().toISOString(),
  feedback: {
    diagnosis_match: diagnosisSimilarity > 60,
    treatment_match: treatmentSimilarity > 60,
    needs_review: diagnosisSimilarity < 40 || treatmentSimilarity < 40
  }
};

return mlData;
